def tail(c,p,src,stop=None):
 s=source(c,p); s=s[s.index(src):];t=modern(c,p)
 if stop:t=t[:t.index(stop)].rstrip()
 e(c,p,t+' '+s)
def plus(c,p,s):e(c,p,modern(c,p)+' '+s)
